import test from 'node:test';import assert from 'node:assert/strict';
import {mkdtemp,readFile,rm} from 'node:fs/promises';import {tmpdir} from 'node:os';import {join} from 'node:path';import {gunzipSync} from 'node:zlib';import {createHash} from 'node:crypto';
import {referenceCases,validateReferenceCases,routeState,observeRoutePoint,gateClass,rectEntry,measureReference,rankReference,aggregateReference} from '../src/dev/s6-reference-pin-comparison.js';
import {Physics} from '../src/physics/physics.js';
import {measurePinAdjustment} from '../src/dev/pin-adjustment-measurement.js';import {saveCompressedRaw,routeSummary} from '../tools/s6-reference-comparison.mjs';
const point=(x,y,time,front=true)=>({x,y,time,front});
test('reference hypotheses and two controls remain separate original-relative legal configurations',()=>{const cs=validateReferenceCases();assert.deepEqual(cs.map(c=>c.moves),[[],[{pinId:2,dx:0,dy:.25}],[{pinId:58,dx:.25,dy:0}],[{pinId:26,dx:.25,dy:-.25}],[{pinId:90,dx:0,dy:-.25}]]);assert.ok(cs.every(c=>c.ballRadius===1.8&&c.normalPower===.14&&c.hesoMouthWidth===12&&c.launchRailProfile==='reference-exit'));});
test('gate finite bounds, direction and repeated touching never turn passes into unique-ball counts',()=>{assert.equal(gateClass(135.99),'left');assert.equal(gateClass(136),'envelope');assert.equal(gateClass(176),'envelope');assert.equal(gateClass(176.01),'right');const s=routeState(9);for(const p of [point(180,710,0),point(180,713,1),point(180,713,2),point(180,715,3),point(180,713,4),point(180,710,5),point(180,715,6)])observeRoutePoint(s,p);assert.equal(s.gatePasses.length,3);assert.deepEqual(s.gatePasses.map(e=>e.direction),['descending','ascending','descending']);assert.equal(s.firstDescending,s.gatePasses[0]);const summary=routeSummary({referenceRoutes:{rows:[{...s,outcome:'out'}]}});assert.equal(summary.firstDescending.right.balls,1);assert.equal(summary.gatePasses['descending:right'],2);assert.equal(summary.gatePasses['ascending:right'],1);const outside=routeState(1);observeRoutePoint(outside,point(221,710,0));observeRoutePoint(outside,point(221,715,1));assert.equal(outside.gatePasses.length,0);const back=routeState(2);observeRoutePoint(back,point(180,710,0,false));observeRoutePoint(back,point(180,715,1,false));assert.equal(back.gatePasses.length,0);});
test('terminal detection catches a full segment crossing, retains first entry and records genuine re-entry',()=>{assert.equal(rectEntry(point(350,840,0),point(410,840,1)),5/60);assert.equal(rectEntry(point(350,880,0),point(410,880,1)),null);const s=routeState(2);for(const p of [point(350,840,0),point(410,840,1),point(390,840,2),point(380,840,3)])observeRoutePoint(s,p);assert.equal(s.terminalEntries.length,2);assert.ok(s.terminalFirstEntry.time<s.terminalEntries[1].time);});
test('route observer leaves all coordinates, outcomes, replay and fixed structure identical',()=>{const c=referenceCases()[0],o={seconds:10,drain:3,replaySeconds:13,replayFPS:30},a=measureReference(c,o,{routeObserver:false}),b=measureReference(c,o);for(const key of ['events','frames','replayFrames','fixed','physical','end','aimObservation'])assert.deepEqual(b[key],a[key],key);assert.equal(b.referenceRoutes.rows.length,b.physical.shots);assert.ok(b.referenceRoutes.rows.some(r=>r.gatePasses.length>0));assert.equal(b.replayFrames.length,391);assert.ok(Math.abs(b.replayFrames.at(-1).time-13)<1e-8);});
test('existing replay defaults remain60Hz and30Hz records full time as an exact subsequence',()=>{const c=referenceCases()[0],o={seconds:2,drain:1,replaySeconds:3},a=measurePinAdjustment(c,o),b=measurePinAdjustment(c,{...o,replayFPS:30});assert.equal(a.replayFPS,60);assert.equal(a.replayFrames.length,181);assert.equal(b.replayFrames.length,91);assert.deepEqual(b.replayFrames,a.replayFrames.filter((_,i)=>i%2===0));assert.deepEqual(a.events,b.events);assert.deepEqual(a.end,b.end);assert.throws(()=>measurePinAdjustment(c,{...o,replayFPS:24}),/replay FPS/);});
const fake=(id,start,returned=0)=>({config:referenceCases().find(c=>c.id===id),physical:{shots:200,reconciled:true,uniqueOutcomeIds:true,allOutcomesFromShots:true,countsMatchOutcomes:true},end:{counts:{start,returned,normal:0},remaining:0},endDiagnostics:{stalled:0},lcdIntrusion:{centreBallIds:[],boundaryOnlyBallIds:[],frontCentreBallIds:[],frontBoundaryOnlyBallIds:[]},observation:{observedFiringGap:{maxGap:100}}});
test('new candidate must strictly beat both controls, keep returns safe and await aim review',()=>{const ids=referenceCases().map(c=>c.id),controls=[fake('original',0),fake('prior-road-pin2',2)];assert.equal(rankReference([...controls,fake('yori58',2)],ids).selected,null);assert.equal(rankReference([...controls,fake('yori58',3)],ids).selected,'yori58');assert.equal(rankReference([...controls,fake('yori58',3)],[]).selected,null);assert.equal(rankReference([...controls,fake('yori58',3,1)],ids).selected,null);const bad=fake('original',0);bad.lcdIntrusion.boundaryOnlyBallIds=[1];assert.equal(rankReference([bad,controls[1],fake('yori58',3)],ids).selected,null);assert.equal(rankReference([...controls,fake('yori58',3),fake('road26',3),fake('jump90',3)],ids).selected,'yori58');});
test('gzip raw records both compressed and expanded SHA with exact roundtrip',async()=>{const dir=await mkdtemp(join(tmpdir(),'s6-compressed-'));try{const r={sourceSHA:'a',configSHA:'b',layoutSHA:'c',replayFPS:30,replayFrames:[],test:'実測保持'},file=join(dir,'test.json.gz'),m=await saveCompressedRaw(file,r),bytes=await readFile(file),plain=gunzipSync(bytes);assert.deepEqual(JSON.parse(plain),r);assert.equal(m.compressedSHA,createHash('sha256').update(bytes).digest('hex'));assert.equal(m.expandedSHA,createHash('sha256').update(plain).digest('hex'));}finally{await rm(dir,{recursive:true,force:true});}});

test('long decision needs all nine rows and improvement over both controls; phase/general/gap deterioration disclosed',()=>{
 const rows=[];for(const id of ['original','prior-road-pin2','yori58'])for(const phase of [.175,.35,.525])rows.push({...fake(id,id==='original'?1:2),phase});
 assert.equal(aggregateReference(rows,'yori58').checks.strictStartRatioAboveBoth,false);
 for(const row of rows.filter(r=>r.config.id==='yori58'))row.end.counts.start=3;
 rows.find(r=>r.config.id==='yori58'&&r.phase===.525).observation.observedFiringGap.maxGap=150;
 rows.find(r=>r.config.id==='original'&&r.phase===.525).end.counts.normal=2;const result=aggregateReference(rows,'yori58');assert.equal(result.checks.strictStartRatioAboveBoth,true);assert.ok(result.perPhase.find(r=>r.phase===.525).againstControls.every(r=>r.maxGapWorse));assert.ok(result.perPhase.find(r=>r.phase===.525).againstControls.find(r=>r.control==='original').generalAdmissionsLower);assert.throws(()=>aggregateReference(rows.slice(1),'yori58'),/nine/);const incomplete=structuredClone(rows);delete incomplete[0].end.counts.normal;assert.throws(()=>aggregateReference(incomplete,'yori58'),/normal admission count/);
});

test('observer throws restore step, advance and pin methods; unobserved routes preserve returned/remaining labels',()=>{
 const methods={step:Physics.prototype.step,advanceBall:Physics.prototype.advanceBall,resolvePins:Physics.prototype.resolvePins};
 assert.throws(()=>measureReference(referenceCases()[0],{seconds:0}),/Unsupported measurement/);for(const [name,fn]of Object.entries(methods))assert.equal(Physics.prototype[name],fn);
 const empty={firstDescending:null,gatePasses:[],terminalFirstEntry:null};const summary=routeSummary({referenceRoutes:{rows:[{...empty,ballId:1,outcome:'returned'},{...empty,ballId:2,outcome:'remaining'}]}});assert.equal(summary.unobservedDescending,2);assert.deepEqual(summary.firstDescending.unobserved.outcomes,{returned:1,remaining:1});assert.equal(summary.firstDescending.unobserved.outcomes.out,undefined);
});
